// Luhn algorithm implementation for credit card validation

function isValidCard(number) {
    // Convert to string and remove spaces
    const cleaned = number.toString().replace(/\s/g, '');

    // Check if all characters are digits
    if (!/^\d+$/.test(cleaned)) {
        return false;
    }

